        "nameEn": "Historical Significance & Archaeological Evidence",
        "detailsOdia": "ଆଧୁନିକ ଐତିହାସିକ ଗବେଷଣା, ଉତ୍କୀର୍ଣ୍ଣ ଶିଳାଲେଖ, ପ୍ରାଚୀନ ମୁଦ୍ରା ଓ ପାଣ୍ଡୁଲିପି ଆଧାରରେ ହରପ୍ପା ସଭ୍ୟତା ଓ ନଗର ର ମହତ୍ତ୍ୱ ନିରୂପିତ ହୋଇଛି। ଏହା ଭାରତୀୟ ସଂସ୍କୃତିର ନିରନ୍ତରତା ଓ ବିକାଶର ପ୍ରମାଣ ଅଟେ।"
