        "detailsOdia": "ଏହି ସମୟରେ ବିକଶିତ ହୋଇଥିବା ସାହିତ୍ୟ, କଳା, ସ୍ଥାପତ୍ୟ, ବାଣିଜ୍ୟ, ପ୍ରଶାସନିକ ସଂସ୍କାର ଏବଂ ଜନସାଧାରଣଙ୍କ ଜୀବନଧାରଣ ଶୈଳୀ ଭାରତୀୟ ସଭ୍ୟତାକୁ ବିଶ୍ୱ ଦରବାରରେ ଏକ ଅନନ୍ୟ ପରିଚୟ ପ୍ରଦାନ କରିଥିଲା।"
