        "detailsOdia": "ଆଧୁନିକ ଐତିହାସିକ ଗବେଷଣା, ଉତ୍କୀର୍ଣ୍ଣ ଶିଳାଲେଖ, ପ୍ରାଚୀନ ମୁଦ୍ରା ଓ ପାଣ୍ଡୁଲିପି ଆଧାରରେ ବୈଦିକ ଧର୍ମ, ଯଜ୍ଞ ଓ ଉପନିଷଦୀୟ ଦର୍ଶନ ର ମହତ୍ତ୍ୱ ନିରୂପିତ ହୋଇଛି। ଏହା ଭାରତୀୟ ସଂସ୍କୃତିର ନିରନ୍ତରତା ଓ ବିକାଶର ପ୍ରମାଣ ଅଟେ।"
