        "detailsOdia": "ଆଧୁନିକ ଐତିହାସିକ ଗବେଷଣା, ଉତ୍କୀର୍ଣ୍ଣ ଶିଳାଲେଖ, ପ୍ରାଚୀନ ମୁଦ୍ରା ଓ ପାଣ୍ଡୁଲିପି ଆଧାରରେ ଚନ୍ଦ୍ରଗୁପ୍ତ ମୌର୍ଯ୍ୟ ଓ ଚାଣକ୍ୟ ର ମହତ୍ତ୍ୱ ନିରୂପିତ ହୋଇଛି। ଏହା ଭାରତୀୟ ସଂସ୍କୃତିର ନିରନ୍ତରତା ଓ ବିକାଶର ପ୍ରମାଣ ଅଟେ।"
