    "summaryOdia": "ଓଡ଼ିଶାର ସୋମ, ଗଙ୍ଗ ଓ ସୂର୍ଯ୍ୟବଂଶୀ ଗଜପତି ସାମ୍ରାଜ୍ୟ ଭାରତୀୟ ଇତିହାସର ଏକ ଅତ୍ୟନ୍ତ ମହତ୍ତ୍ୱପୂର୍ଣ୍ଣ ଅଧ୍ୟାୟ। ଏହି ବିଭାଗରେ ଏହାର ଉତ୍ଥାନ, ମୁଖ୍ୟ ଘଟଣାବଳୀ, ସାମାଜିକ ଓ ରାଜନୈତିକ ପ୍ରଭାବ, ସାଂସ୍କୃତିକ ଉପଲବ୍ଧି ଏବଂ ଐତିହାସିକ ପ୍ରମାଣର ବିସ୍ତୃତ ବୈଜ୍ଞାନିକ ବିଶ୍ଳେଷଣ ପ୍ରଦାନ କରାଯାଇଛି। ପ୍ରତ୍ନତାତ୍ତ୍ୱିକ ଉତ୍ଖନନ, ଶିଳାଲେଖ ଓ ପ୍ରାଥମିକ ଐତିହାସିକ ଗ୍ରନ୍ଥଗୁଡ଼ିକ ଏହାର ସତ୍ୟତାକୁ ପ୍ରତିପାଦନ କରେ।",
