        "detailsOdia": "କୃଷି, ଶିଳ୍ପ, ବାଣିଜ୍ୟ ଓ ମୁଦ୍ରା ବ୍ୟବସ୍ଥାର ଐତିହାସିକ ବିକାଶ କାଳଖଣ୍ଡରେ ଘଟିଥିବା ପ୍ରମୁଖ ଘଟଣା, ରାଜନୈତିକ ନେତୃତ୍ୱ, ଶାସନ ପ୍ରଣାଳୀ ଏବଂ ଜନଜୀବନ ଉପରେ ଏହାର ଦୀର୍ଘକାଳୀନ ପ୍ରଭାବ ସମ୍ପର୍କରେ ତଥ୍ୟଭିତ୍ତିକ ଆଲୋଚନା। ସମକାଳୀନ ଉତ୍ସଗୁଡ଼ିକରୁ ମିଳୁଥିବା ପ୍ରମାଣ ଆଧାରରେ ଏହାର ବିକାଶ ଧାରାକୁ ବିଶ୍ଳେଷଣ କରାଯାଇଛି।"
